#include <string>
#include <algorithm>

using namespace std;

class Solution {
public:
    int maxActiveSectionsAfterTrade(string s) {
        int n = s.length();
        int ans = 0;
        int i = 0;
        int pre = -1e9;
        int mx = 0;

        while (i < n) {
            int j = i;
            while (j < n && s[j] == s[i]) {
                j++;
            }
            int cur = j - i;

            if (s[i] == '1') {
                ans += cur;
            } else {
                mx = max(mx, pre + cur);
                pre = cur;
            }
            i = j;
        }

        return ans + mx;
    }
};

class Solution {
    public int maxActiveSectionsAfterTrade(String s) {
        int n = s.length();
        int ans = 0;
        int i = 0;
        int pre = -1000000000;
        int mx = 0;

        while (i < n) {
            int j = i;
            while (j < n && s.charAt(j) == s.charAt(i)) {
                j++;
            }
            int cur = j - i;

            if (s.charAt(i) == '1') {
                ans += cur;
            } else {
                mx = Math.max(mx, pre + cur);
                pre = cur;
            }
